def calendar(i,name,fri=8,six=False):
 week=[]
 for d in range(1,8):
  hours=fri if d==6 else 8
  intervals=[{'start':540,'end':780},{'start':840,'end':840+int((hours-4)*60)}] if d in [2,3,4,5,6]+([7] if six else []) else []
  week.append({'weekday':d,'intervals':intervals})
 return {'id':i,'name':name,'week':week,'exceptions':[]}
